46	#define SATP_MODE_SV39 8
47	#define SATP_MODE_SV48 9
48	#define SATP_ASID_SHIFT 44lu
49	#define SATP_MODE_SHIFT 60lu
50	
51	static inline void set_satp(
52	    unsigned mode, unsigned asid, unsigned long ppn)
53	{
54	    unsigned long __v =
55	        (unsigned long)(((unsigned long)mode << SATP_MODE_SHIFT) | ((unsigned long)asid << SATP_ASID_SHIFT) | ppn);
56	    __asm__ __volatile__("sfence.vma\ncsrw satp, %0" : : "rK"(__v) : "memory");
57	}
