111	typedef struct elf64_phdr
112	{
113	    Elf64_Word p_type;
114	    Elf64_Word p_flags;
115	    Elf64_Off p_offset;   /* Segment file offset */
116	    Elf64_Addr p_vaddr;   /* Segment virtual address */
117	    Elf64_Addr p_paddr;   /* Segment physical address */
118	    Elf64_Xword p_filesz; /* Segment size in file */
119	    Elf64_Xword p_memsz;  /* Segment size in memory */
120	    Elf64_Xword p_align;  /* Segment alignment, file & memory */
121	} Elf64_Phdr;
