28	char *escaped_file_content(FILE *f, int *file_size)
29	{
30	    static char *buff = NULL;
31	    static int size   = 1;
32	    int length        = 0;
33	    int ch;
34	
35	    *file_size = 0;
36	    while ((ch = fgetc(f)) != EOF) {
37	        if (length + 6 >= size) {
38	            size *= 2;
39	            buff = realloc(buff, size);
40	        }
41	
42	        assert(buff != NULL);
43	
44	        *file_size     = (*file_size) + 1;
45	        buff[length++] = '0';
46	        buff[length++] = 'x';
47	        buff[length++] = to_hex((ch & 0xf0) >> 4);
48	        buff[length++] = to_hex(ch & 0xf);
49	        buff[length++] = ',';
50	
51	        if ((*file_size) % 16 == 0) {
52	            buff[length++] = '\n';
53	        }
54	    }
55	    return buff;
56	}
