33	void simplify_filter(char* dest, char* src, const char* pattern)
34	{
35	    //int length         = strlen(src);
36	    int length_pattern = strlen(pattern);
37	    char* next         = strstr(src, pattern);
38	    while (*src != '\0') {
39	        while (src != next && *src != '\0') {
40	            *dest = *src;
41	            ++dest;
42	            ++src;
43	        }
44	        if (*src == '\0') break;
45	
46	        src += length_pattern;
47	        next = strstr(src, pattern);
48	    }
49	    *dest = '\0';
50	}
