// returns pa
ptr_t alloc_user_page(uint8_t pin, PTE* pgtable)
{
    int i;
    for(i = 0; i < USER_PAGE_NUM; i++){
        if(user_page[i].valid == 0){
            break;
        }
    }
    if(i == USER_PAGE_NUM){
        /* no free user page: evict one to the swap area on SD card */
        ptr_t victim = selete_page();
        write_to_sd(victim);
        i = pa2num(victim);
    }
    user_page[i].valid = 1;
    user_page[i].pin = pin;
    user_page[i].pgtable = pgtable;
    return num2pa(i);
}

// select a user page to write to disk (NRU), returns pa
ptr_t selete_page()
{
    /* NRU (clock) algorithm: give recently accessed pages a second
     * chance by clearing their _PAGE_ACCESSED bit, and select the
     * first valid, unpinned page whose accessed bit is 0 */
    static int clock_hand = 0;
    while(1){
        int i = clock_hand;
        clock_hand = (clock_hand + 1) % USER_PAGE_NUM;
        if(user_page[i].valid == 0 || user_page[i].pin != 0){
            continue;
        }
        PTE *pte = user_page[i].pgtable;
        if(pte == NULL){
            continue;
        }
        if(get_attribute(*pte, _PAGE_ACCESSED)){
            clear_attribute(pte, _PAGE_ACCESSED);
            continue;
        }
        return num2pa(i);
    }
}

void write_to_sd(ptr_t pa)
{
    /* find a free slot in the swap area */
    int i;
    for(i = 0; i < DISK_PAGE_NUM; i++){
        if(disk_page[i].valid == 0){
            break;
        }
    }
    assert(i != DISK_PAGE_NUM);
    disk_page[i].valid = 1;

    /* one page = 8 sd blocks(512B), swap area starts at SWAP_BEGIN */
    sbi_sd_write((unsigned int)pa, PAGE_SIZE / 512,
                 SWAP_BEGIN + i * (PAGE_SIZE / 512));

    /* mark the owner's pte as swapped out: clear _PAGE_PRESENT,
     * set _PAGE_SOFT and record the disk slot number in pfn */
    PTE *pte = user_page[pa2num(pa)].pgtable;
    if(pte != NULL){
        clear_attribute(pte, _PAGE_PRESENT);
        set_attribute(pte, _PAGE_SOFT);
        set_pfn(pte, i);
    }

    /* the physical page is free now */
    user_page[pa2num(pa)].valid = 0;
    flush_tlb_all();
}

