#define USER_CODE_BEGIN 0x10000lu
#define USER_CODE_END   0x13000lu
#define SHM_BASE        0x1000lu

/*
 * walk the 3-level sv39 page table (pgdir is pa) for `va`;
 * when `alloc` is non-zero, missing intermediate levels are
 * allocated from the pgdir page pool.
 * returns the kva of the leaf pte, or NULL if not present.
 */
static PTE *get_leaf_pte(uintptr_t va, PTE *pgdir, int alloc)
{
    PTE *pgdir_kva = (PTE *)pa2kva((uintptr_t)pgdir);
    uint64_t vpn2 = (va >> VPN2_SHIFT) & VPN_MASK;
    uint64_t vpn1 = (va >> VPN1_SHIFT) & VPN_MASK;
    uint64_t vpn0 = (va >> VPN0_SHIFT) & VPN_MASK;

    if(!get_attribute(pgdir_kva[vpn2], _PAGE_PRESENT)){
        if(!alloc){
            return NULL;
        }
        PTE *new_pgdir = alloc_pgdir_page();
        set_pfn(&pgdir_kva[vpn2], (uintptr_t)new_pgdir >> NORMAL_PAGE_SHIFT);
        set_attribute(&pgdir_kva[vpn2], _PAGE_PRESENT);
    }
    PTE *second_kva = (PTE *)pa2kva(get_pa(pgdir_kva[vpn2]));

    if(!get_attribute(second_kva[vpn1], _PAGE_PRESENT)){
        if(!alloc){
            return NULL;
        }
        PTE *new_pgdir = alloc_pgdir_page();
        set_pfn(&second_kva[vpn1], (uintptr_t)new_pgdir >> NORMAL_PAGE_SHIFT);
        set_attribute(&second_kva[vpn1], _PAGE_PRESENT);
    }
    PTE *last_kva = (PTE *)pa2kva(get_pa(second_kva[vpn1]));

    return &last_kva[vpn0];
}

/*
 * Virtual Memory Layout
 * 0x0_0000_1000 ~ 0x0_0001_0000: share
 * 0x0_0001_0000 ~ 0x0_0001_3000: code
 * 0xf_0000_f000 ~ 0xf_0001_0000: stack
 */
PTE* init_page_table()
{
    PTE *pgdir = alloc_pgdir_page();
    PTE *pgdir_kva = (PTE *)pa2kva((uintptr_t)pgdir);

    /* share the kernel mapping (kva area) with the kernel page table,
     * so that the kernel is mapped in every process's address space */
    PTE *kernel_pgdir = (PTE *)pa2kva(PGDIR_PA);
    pgdir_kva[0x101] = kernel_pgdir[0x101];

    /* pre-allocate and map the user code region, so that load_elf()
     * can copy the segments through get_kva_of() */
    for(uintptr_t va = USER_CODE_BEGIN; va < USER_CODE_END; va += PAGE_SIZE){
        PTE *leaf = get_leaf_pte(va, pgdir, 1);
        ptr_t pa = alloc_user_page(0, leaf);
        clear_pgdir((PTE *)pa2kva(pa));
        set_pfn(leaf, pa >> NORMAL_PAGE_SHIFT);
        set_attribute(leaf, _PAGE_PRESENT | _PAGE_READ | _PAGE_WRITE |
                            _PAGE_EXEC | _PAGE_USER |
                            _PAGE_ACCESSED | _PAGE_DIRTY);
    }

    return pgdir;
}

void free_process_user_page(PTE* pgdir)
{
    PTE *pgdir_kva = (PTE *)pa2kva((uintptr_t)pgdir);
    for(int i = 0; i < NUM_PTE_ENTRY; i++){
        if(!get_attribute(pgdir_kva[i], _PAGE_PRESENT)){
            continue;
        }
        if(i == 0x101){
            /* the kernel mapping is shared, do not free it */
            continue;
        }
        PTE *second_kva = (PTE *)pa2kva(get_pa(pgdir_kva[i]));
        for(int j = 0; j < NUM_PTE_ENTRY; j++){
            if(!get_attribute(second_kva[j], _PAGE_PRESENT)){
                continue;
            }
            PTE *last_kva = (PTE *)pa2kva(get_pa(second_kva[j]));
            for(int k = 0; k < NUM_PTE_ENTRY; k++){
                uintptr_t va = ((uintptr_t)i << VPN2_SHIFT) |
                               ((uintptr_t)j << VPN1_SHIFT) |
                               ((uintptr_t)k << VPN0_SHIFT);
                if(get_attribute(last_kva[k], _PAGE_SOFT)){
                    /* the page is in the swap area, free the disk slot */
                    disk_page[get_pfn(last_kva[k])].valid = 0;
                    continue;
                }
                if(!get_attribute(last_kva[k], _PAGE_PRESENT)){
                    continue;
                }
                uintptr_t pa = get_pa(last_kva[k]);
                if(va >= SHM_BASE && va < USER_CODE_BEGIN){
                    /* shared page: only freed when the last user detaches */
                    int key = (va - SHM_BASE) / PAGE_SIZE;
                    shm_page[key].count--;
                    if(shm_page[key].count == 0){
                        free_user_page(pa);
                        shm_page[key].pa = 0;
                    }
                }
                else{
                    free_user_page(pa);
                }
            }
            free_pgdir_page(kva2pa((uintptr_t)last_kva));
        }
        free_pgdir_page(kva2pa((uintptr_t)second_kva));
    }
    free_pgdir_page((uintptr_t)pgdir);
}

uintptr_t shm_page_get(int key)
{
    if(key < 0 || key >= SHM_PAGE_NUM){
        return 0;
    }
    uintptr_t va = SHM_BASE + key * PAGE_SIZE;
    PTE *pgdir = current_running[cpu_id]->pgdir;
    PTE *leaf = get_leaf_pte(va, pgdir, 1);

    if(shm_page[key].count == 0){
        /* first user: allocate the physical shared page */
        uintptr_t pa = alloc_user_page(1, NULL);
        clear_pgdir((PTE *)pa2kva(pa));
        shm_page[key].pa = pa;
    }
    shm_page[key].count++;

    set_pfn(leaf, shm_page[key].pa >> NORMAL_PAGE_SHIFT);
    set_attribute(leaf, _PAGE_PRESENT | _PAGE_READ | _PAGE_WRITE |
                        _PAGE_USER | _PAGE_ACCESSED | _PAGE_DIRTY);
    local_flush_tlb_all();
    return va;
}

void shm_page_dt(uintptr_t addr)
{
    int key = (addr - SHM_BASE) / PAGE_SIZE;
    if(key < 0 || key >= SHM_PAGE_NUM){
        return;
    }
    PTE *pgdir = current_running[cpu_id]->pgdir;
    PTE *leaf = get_leaf_pte(addr, pgdir, 0);
    if(leaf != NULL){
        *leaf = 0;
    }
    local_flush_tlb_all();

    shm_page[key].count--;
    if(shm_page[key].count <= 0){
        shm_page[key].count = 0;
        free_user_page(shm_page[key].pa);
        shm_page[key].pa = 0;
    }
}

void handle_page_fault(regs_context_t *regs, uint64_t stval, uint64_t cause)
{
    /* kernel must not page fault */
    if(stval >= KERNEL_MEM_OFFSET){
        handle_other(regs, stval, cause);
        return;
    }

    uintptr_t va = stval & VA_MASK;
    PTE *pgdir = current_running[cpu_id]->pgdir;
    PTE *leaf = get_leaf_pte(va, pgdir, 1);

    if(get_attribute(*leaf, _PAGE_SOFT)){
        /* the page was swapped out: swap it back in */
        int slot = get_pfn(*leaf);
        ptr_t pa = alloc_user_page(0, leaf);
        sbi_sd_read((unsigned int)pa, PAGE_SIZE / 512,
                    SWAP_BEGIN + slot * (PAGE_SIZE / 512));
        disk_page[slot].valid = 0;
        clear_attribute(leaf, _PAGE_SOFT);
        set_pfn(leaf, pa >> NORMAL_PAGE_SHIFT);
        set_attribute(leaf, _PAGE_PRESENT | _PAGE_READ | _PAGE_WRITE |
                            _PAGE_EXEC | _PAGE_USER |
                            _PAGE_ACCESSED | _PAGE_DIRTY);
    }
    else{
        /* demand paging: allocate a fresh, zeroed page */
        ptr_t pa = alloc_user_page(0, leaf);
        clear_pgdir((PTE *)pa2kva(pa));
        set_pfn(leaf, pa >> NORMAL_PAGE_SHIFT);
        set_attribute(leaf, _PAGE_PRESENT | _PAGE_READ | _PAGE_WRITE |
                            _PAGE_EXEC | _PAGE_USER |
                            _PAGE_ACCESSED | _PAGE_DIRTY);
    }

    local_flush_tlb_all();
    /* return without advancing sepc: re-execute the faulting instruction */
}

