args.new_string:
/* 
 * Only modify PCB, current_running, process_id and ready_queue
 * DO NOT STORE OR RESTORE 
 * trick: modify $tp in ret_from_exception to ensure
 * disable_preempt() and enable_preempt() modify the same PCB
 */
void scheduler(void)
{
    /* pick the next task before requeueing the current one, so that
     * the current task can keep running when nothing else is ready */
    list_node_t *next_node = max_priority_node();
    if(next_node == NULL){
        return;
    }

    pcb_t *cur_running = current_running[cpu_id];
    if(cur_running->status == TASK_RUNNING){
        cur_running->status = TASK_READY;
        cur_running->ready_tick = get_ticks();
        list_add_tail(&cur_running->list, &ready_queue);
    }

    pcb_t *next_running = list_entry(next_node, pcb_t, list);
    list_del(next_node);
    next_running->status = TASK_RUNNING;
    next_running->cpu_id = cpu_id;

    current_running[cpu_id] = next_running;
    /* ret_from_exception() switches to $tp = current_cpu_running */
    current_cpu_running = next_running;

    /* switch the address space */
    set_satp(SATP_MODE_SV39, 0,
             ((uintptr_t)next_running->pgdir) >> NORMAL_PAGE_SHIFT);
    local_flush_tlb_all();
}

pid_t do_exec(const char* file_name, int argc, char* argv[], spawn_mode_t mode)
{
    /* find a free pcb */
    int i;
    for(i = 0; i < NUM_MAX_TASK; i++){
        if(pcb[i].pid == -1){
            break;
        }
    }
    if(i == NUM_MAX_TASK){
        return 0;    /* too many tasks */
    }

    /* the arguments live in the caller's address space */
    enable_sum();

    /* find the elf file */
    unsigned char *binary = NULL;
    int length = 0;
    if(get_elf_file(file_name, &binary, &length) == 0){
        disable_sum();
        return -1;   /* no such process */
    }

    /* copy the arguments into a kernel buffer */
    char arg_buf[16][32];
    if(argc > 16){
        argc = 16;
    }
    for(int j = 0; j < argc; j++){
        strcpy(arg_buf[j], argv[j]);
    }
    disable_sum();

    /* initialize the pcb (mirrors init_pcb() in main.c) */
    pcb[i].kernel_sp = pa2kva(alloc_user_page(1, NULL) + PAGE_SIZE);
    pcb[i].user_sp = USER_STACK_ADDR;
    pcb[i].preempt_count = 0;
    pcb[i].kernel_stack_base = pcb[i].kernel_sp;
    pcb[i].user_stack_base = pcb[i].user_sp;
    list_add_tail(&pcb[i].list, &ready_queue);
    init_list_head(&pcb[i].wait_list);
    pcb[i].binsem_num = 0;
    pcb[i].pid = process_id++;
    pcb[i].type = USER_PROCESS;
    pcb[i].status = TASK_READY;
    pcb[i].mode = mode;
    pcb[i].priority = 0;
    pcb[i].ready_tick = get_ticks();
    pcb[i].mask = 3;
    pcb[i].cpu_id = cpu_id;
    pcb[i].pgdir = init_page_table();

    /* load the elf segments into the new address space */
    uintptr_t entry = load_elf(binary, length, (uintptr_t)pcb[i].pgdir, get_kva_of);

    /* allocate and map one page for the user stack */
    PTE *stack_pte = get_leaf_pte(USER_STACK_ADDR - PAGE_SIZE, pcb[i].pgdir, 1);
    ptr_t stack_pa = alloc_user_page(0, stack_pte);
    clear_pgdir((PTE *)pa2kva(stack_pa));
    set_pfn(stack_pte, stack_pa >> NORMAL_PAGE_SHIFT);
    set_attribute(stack_pte, _PAGE_PRESENT | _PAGE_READ | _PAGE_WRITE |
                             _PAGE_USER | _PAGE_ACCESSED | _PAGE_DIRTY);

    /* push the argument strings on the top of the user stack */
    uintptr_t user_sp = USER_STACK_ADDR;
    uintptr_t stack_kva = pa2kva(stack_pa) + PAGE_SIZE;
    uintptr_t arg_va[16];
    for(int j = 0; j < argc; j++){
        int len = strlen(arg_buf[j]) + 1;
        user_sp -= len;
        stack_kva -= len;
        strcpy((char *)stack_kva, arg_buf[j]);
        arg_va[j] = user_sp;
    }
    /* push the argv pointer array */
    user_sp = ROUNDDOWN(user_sp, sizeof(uintptr_t));
    stack_kva = ROUNDDOWN(stack_kva, sizeof(uintptr_t));
    user_sp -= argc * sizeof(uintptr_t);
    stack_kva -= argc * sizeof(uintptr_t);
    memcpy((uint8_t *)stack_kva, (uint8_t *)arg_va, argc * sizeof(uintptr_t));
    uintptr_t argv_user = user_sp;
    /* sp must be 16-byte aligned at entry */
    user_sp = ROUNDDOWN(user_sp, 16);

    /* initialize the register context on the kernel stack
     * (mirrors init_pcb_stack() in main.c) */
    regs_context_t *pt_regs = (regs_context_t *)(pcb[i].kernel_sp - sizeof(regs_context_t));
    pcb[i].kernel_sp -= sizeof(regs_context_t);
    pt_regs->regs[1] = (reg_t)entry;            // ra
    pt_regs->regs[2] = (reg_t)user_sp;          // sp
    pt_regs->regs[3] = (reg_t)__global_pointer$;// gp
    pt_regs->regs[10] = (reg_t)argc;            // a0
    pt_regs->regs[11] = (reg_t)argv_user;       // a1
    pt_regs->sstatus = (reg_t)SR_SPIE;          // SPP = 0, SPIE = 1
    pt_regs->sepc = (reg_t)entry;               // sepc
    pt_regs->sscratch = (reg_t)&pcb[i];         // sscratch = tp

    return pcb[i].pid;
}

/* release all the binsem locks acquired by `p` */
static void release_binsem(pcb_t *p)
{
    for(int i = 0; i < p->binsem_num; i++){
        int binsem_id = p->binsem_id[i];
        binsem_nodes[binsem_id].sem++;
        if(binsem_nodes[binsem_id].sem <= 0){
            list_node_t *unblocked_node = binsem_nodes[binsem_id].block_queue.next;
            pcb_t *unblocked_pcb = list_entry(unblocked_node, pcb_t, list);
            unblocked_pcb->binsem_id[unblocked_pcb->binsem_num] = binsem_id;
            unblocked_pcb->binsem_num++;
            do_unblock(unblocked_node);
        }
    }
    p->binsem_num = 0;
}

void do_exit()
{
    pcb_t *exit_pcb = current_running[cpu_id];

    /* release the acquired binsem locks */
    release_binsem(exit_pcb);

    /* release the address space: user pages, swap slots and page table */
    free_process_user_page(exit_pcb->pgdir);

    /* wake up the processes waiting for this one */
    while(!list_empty(&exit_pcb->wait_list)){
        do_unblock(exit_pcb->wait_list.next);
    }

    if(exit_pcb->mode == ENTER_ZOMBIE_ON_EXIT){
        /* keep the pcb so that do_waitpid() can find and reap it */
        exit_pcb->status = TASK_ZOMBIE;
    }
    else{
        /* hand over to the reaper in main(): it releases the pcb
         * and the kernel stack (we are still running on it) */
        exit_pcb->status = TASK_EXITED;
        list_add_tail(&exit_pcb->list, &kernel_pcb[0].wait_list);
    }

    scheduler();
}

