/*
 * walk the 3-level sv39 page table (pgdir is pa) for `va`,
 * allocating missing intermediate levels from the pgdir page pool;
 * returns the kva of the leaf pte.
 */
static PTE *walk_pgtable(uintptr_t va, PTE *pgdir)
{
    PTE *pgdir_kva = (PTE *)pa2kva((uintptr_t)pgdir);
    uint64_t vpn2 = (va >> VPN2_SHIFT) & VPN_MASK;
    uint64_t vpn1 = (va >> VPN1_SHIFT) & VPN_MASK;
    uint64_t vpn0 = (va >> VPN0_SHIFT) & VPN_MASK;

    if(!get_attribute(pgdir_kva[vpn2], _PAGE_PRESENT)){
        PTE *new_pgdir = alloc_pgdir_page();
        set_pfn(&pgdir_kva[vpn2], (uintptr_t)new_pgdir >> NORMAL_PAGE_SHIFT);
        set_attribute(&pgdir_kva[vpn2], _PAGE_PRESENT);
    }
    PTE *second_kva = (PTE *)pa2kva(get_pa(pgdir_kva[vpn2]));

    if(!get_attribute(second_kva[vpn1], _PAGE_PRESENT)){
        PTE *new_pgdir = alloc_pgdir_page();
        set_pfn(&second_kva[vpn1], (uintptr_t)new_pgdir >> NORMAL_PAGE_SHIFT);
        set_attribute(&second_kva[vpn1], _PAGE_PRESENT);
    }
    PTE *last_kva = (PTE *)pa2kva(get_pa(second_kva[vpn1]));

    return &last_kva[vpn0];
}

