int do_kill(pid_t pid)
{
    /* kernel processes and the shell cannot be killed */
    if(pid <= 1){
        return 0;
    }

    /* search the pcb */
    pcb_t *kill_pcb = NULL;
    for(int i = 0; i < NUM_MAX_TASK; i++){
        if(pcb[i].pid == pid){
            kill_pcb = &pcb[i];
            break;
        }
    }
    if(kill_pcb == NULL){
        return 0;
    }

    /* killing itself is just exiting */
    if(kill_pcb == current_running[cpu_id]){
        do_exit();
        return 1;
    }

    /* remove it from the queue(ready/blocked/sleep) it is in */
    list_del(&kill_pcb->list);

    /* release the acquired binsem locks */
    release_binsem(kill_pcb);

    /* release the address space: user pages, swap slots and page table */
    free_process_user_page(kill_pcb->pgdir);

    /* wake up the processes waiting for this one */
    while(!list_empty(&kill_pcb->wait_list)){
        do_unblock(kill_pcb->wait_list.next);
    }

    /* it is not running on this core, so release the kernel
     * stack and the pcb directly */
    free_user_page(kva2pa(kill_pcb->kernel_stack_base - PAGE_SIZE));
    kill_pcb->status = TASK_EXITED;
    kill_pcb->pid = -1;
    return 1;
}

int do_waitpid(pid_t pid, reg_t ignore1, reg_t ignore2, reg_t ignore3, regs_context_t *regs)
{
    while(1){
        /* search the pcb */
        pcb_t *wait_pcb = NULL;
        for(int i = 0; i < NUM_MAX_TASK; i++){
            if(pcb[i].pid == pid){
                wait_pcb = &pcb[i];
                break;
            }
        }
        if(wait_pcb == NULL){
            return -1;
        }

        if(wait_pcb->status == TASK_ZOMBIE){
            /* reap the zombie: release its kernel stack and pcb */
            free_user_page(kva2pa(wait_pcb->kernel_stack_base - PAGE_SIZE));
            wait_pcb->status = TASK_EXITED;
            wait_pcb->pid = -1;
            return pid;
        }
        if(wait_pcb->status == TASK_EXITED){
            return pid;
        }

        /* block until the target process exits */
        do_block(&current_running[cpu_id]->list, &wait_pcb->wait_list);
        scheduler();
    }
}

