args.new_string:
list_node_t* max_priority_node(void)
{
    /* choose the ready task with the highest priority that is allowed
     * to run on this core; ties are broken by the earliest ready_tick
     * (first-come-first-served) */
    list_node_t *best = NULL;
    unsigned long cpu_mask = 1lu << cpu_id;
    list_node_t *node = ready_queue.next;
    while(node != &ready_queue){
        pcb_t *p = list_entry(node, pcb_t, list);
        if(p->mask & cpu_mask){
            if(best == NULL){
                best = node;
            }
            else{
                pcb_t *b = list_entry(best, pcb_t, list);
                if(p->priority > b->priority ||
                   (p->priority == b->priority && p->ready_tick < b->ready_tick)){
                    best = node;
                }
            }
        }
        node = node->next;
    }
    return best;
}

